import{_ as o,C as l,o as a,c as i,a4 as n,E as r}from"./chunks/framework.3hqjI0F0.js";const y=JSON.parse('{"title":"API Explorer - Tra cứu 333 API Zalo SDK (12 Domains)","description":"Công cụ tìm kiếm và lọc trực tiếp toàn bộ 333 API nguyên bản của @softtynet/zca-js chia theo 12 phân hệ: Auth, Chat, Group, Friend, Profile, Sync, ZCloud, Call, Media, Sticker, Board, Business.","frontmatter":{"title":"API Explorer - Tra cứu 333 API Zalo SDK (12 Domains)","description":"Công cụ tìm kiếm và lọc trực tiếp toàn bộ 333 API nguyên bản của @softtynet/zca-js chia theo 12 phân hệ: Auth, Chat, Group, Friend, Profile, Sync, ZCloud, Call, Media, Sticker, Board, Business.","head":[["link",{"rel":"canonical","href":"https://softtyos.github.io/zca-js-docs/api/"}],["meta",{"property":"og:url","content":"https://softtyos.github.io/zca-js-docs/api/"}],["meta",{"property":"og:title","content":"API Explorer - Tra cứu 333 API Zalo SDK (12 Domains)"}],["meta",{"property":"og:description","content":"Công cụ tìm kiếm và lọc trực tiếp toàn bộ 333 API nguyên bản của @softtynet/zca-js chia theo 12 phân hệ: Auth, Chat, Group, Friend, Profile, Sync, ZCloud, Call, Media, Sticker, Board, Business."}]]},"headers":[],"relativePath":"api/index.md","filePath":"api/index.md","lastUpdated":1793200976000}'),s={name:"api/index.md"};function h(d,t,c,g,p,u){const e=l("ApiExplorer");return a(),i("div",null,[t[0]||(t[0]=n('<h1 id="⚡-tra-cuu-loc-truc-tiep-api-reference" tabindex="-1">⚡ Tra cứu &amp; Lọc trực tiếp API Reference <a class="header-anchor" href="#⚡-tra-cuu-loc-truc-tiep-api-reference" aria-label="Permalink to &quot;⚡ Tra cứu &amp; Lọc trực tiếp API Reference&quot;">​</a></h1><p>Thư viện <strong><code>@softtynet/zca-js</code> (v2.3.12)</strong> cung cấp tổng cộng <strong>333 API nguyên bản</strong> được tổ chức khoa học thành <strong>12 Domains</strong> theo đúng kiến trúc Zalo PC <code>26.7.10</code>.</p><blockquote><p>🤖 <strong>Dành cho AI Agents (Cursor, Antigravity, Claude, ChatGPT)</strong>: Bạn có thể nạp trực tiếp ngữ cảnh toàn bộ 333 API qua chuẩn AI SEO tại <a href="https://softtyos.github.io/zca-js-docs/llms.txt" target="_blank" rel="noreferrer"><code>/llms.txt</code></a> hoặc bản đầy đủ <a href="https://softtyos.github.io/zca-js-docs/llms-full.txt" target="_blank" rel="noreferrer"><code>/llms-full.txt</code></a>.</p></blockquote><p>Sử dụng thanh công cụ bên dưới để lọc tức thì theo <strong>Phân hệ</strong>, <strong>HTTP Method (<code>GET</code>/<code>POST</code>)</strong>, <strong>Tên hàm</strong> hoặc <strong>Endpoint Zalo</strong> và sao chép nhanh cú pháp gọi hàm:</p>',4)),r(e),t[1]||(t[1]=n('<h2 id="bang-tong-hop-12-phan-he-domains" tabindex="-1">Bảng tổng hợp 12 Phân hệ (Domains) <a class="header-anchor" href="#bang-tong-hop-12-phan-he-domains" aria-label="Permalink to &quot;Bảng tổng hợp 12 Phân hệ (Domains)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Phân hệ</th><th style="text-align:left;">Namespace</th><th style="text-align:center;">Số lượng API</th><th style="text-align:left;">Chức năng chính</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="./auth.html"><strong>🔐 Xác thực &amp; Phiên (Auth)</strong></a></td><td style="text-align:left;"><code>api.auth</code></td><td style="text-align:center;"><strong>14</strong></td><td style="text-align:left;">Quản lý thiết bị đăng nhập, xuất/nhập phiên (exportSession), mã QR, Keep-Alive, đổi mật khẩu, E2EE và giải mã GID (Global ID) / Noised ID.</td></tr><tr><td style="text-align:left;"><a href="./chat.html"><strong>💬 Tin nhắn, Hội thoại &amp; Dịch AI (Chat)</strong></a></td><td style="text-align:left;"><code>api.chat</code></td><td style="text-align:center;"><strong>52</strong></td><td style="text-align:left;">Gửi/nhận tin nhắn văn bản, ảnh, video, voice, card, thu hồi tin nhắn, Dịch đa ngôn ngữ bằng Zalo AI, đánh dấu tin nhắn quan trọng, chặn chia sẻ và trạng thái Đã nhận/Đã xem.</td></tr><tr><td style="text-align:left;"><a href="./group.html"><strong>👥 Nhóm &amp; Cộng đồng (Group)</strong></a></td><td style="text-align:left;"><code>api.group</code></td><td style="text-align:center;"><strong>46</strong></td><td style="text-align:left;">Quản lý nhóm &amp; Cộng đồng, lấy thông tin nhóm (V1/V2/V3/V4), lịch sử tin nhắn Cloud, trạng thái tin nhắn thành viên, chủ đề (Topic) và phân quyền.</td></tr><tr><td style="text-align:left;"><a href="./friend.html"><strong>🤝 Bạn bè &amp; Danh bạ (Friend)</strong></a></td><td style="text-align:left;"><code>api.friend</code></td><td style="text-align:center;"><strong>37</strong></td><td style="text-align:left;">Quản lý danh sách bạn bè, lời mời kết bạn, gợi ý kết bạn, biệt danh (alias), chặn, đồng bộ danh bạ và kiểm tra trạng thái hoạt động PC/Web.</td></tr><tr><td style="text-align:left;"><a href="./profile.html"><strong>🪪 Hồ sơ cá nhân &amp; Emoji Status (Profile)</strong></a></td><td style="text-align:left;"><code>api.profile</code></td><td style="text-align:center;"><strong>22</strong></td><td style="text-align:left;">Thông tin tài khoản, Mini Profile, đổi ảnh đại diện, cài đặt quyền riêng tư, trạng thái cảm xúc (Emoji Status), hồ sơ Doanh nghiệp và xác thực EKYC.</td></tr><tr><td style="text-align:left;"><a href="./sync.html"><strong>🔄 Đồng bộ Mobile ZDB 4.0 (Sync)</strong></a></td><td style="text-align:left;"><code>api.sync</code></td><td style="text-align:center;"><strong>10</strong></td><td style="text-align:left;">Đồng bộ toàn bộ lịch sử tin nhắn từ điện thoại sang PC qua giao thức RSA-2048 &amp; ZDB 4.0 AES-256-CBC multi-chunk, kiểm tra Backup, Cross-DB và đồng bộ hành động Media.</td></tr><tr><td style="text-align:left;"><a href="./zcloud.html"><strong>☁️ Đám mây ZCloud &amp; ZFamily (ZCloud)</strong></a></td><td style="text-align:left;"><code>api.zcloud</code></td><td style="text-align:center;"><strong>16</strong></td><td style="text-align:left;">Truy vấn dung lượng My Cloud / ZCloud, ZFamily, khóa giải mã ViewerKey (98yS AES-256-CBC), lấy link tải hàng loạt, quản lý hàng đợi và di chuyển dữ liệu.</td></tr><tr><td style="text-align:left;"><a href="./call.html"><strong>📞 Gọi thoại, Video &amp; Gọi nhóm (Call)</strong></a></td><td style="text-align:left;"><code>api.call</code></td><td style="text-align:center;"><strong>30</strong></td><td style="text-align:left;">Điều khiển trọn vẹn 30 API cuộc gọi thoại, video 1-1, gọi nhóm và bộ máy Call Engine (ZaloRtcSession UDP/SRTP 2 chiều &amp; ZaloCallController).</td></tr><tr><td style="text-align:left;"><a href="./media.html"><strong>🖼️ Kho lưu trữ &amp; Chuyển giọng nói (Media)</strong></a></td><td style="text-align:left;"><code>api.media</code></td><td style="text-align:center;"><strong>8</strong></td><td style="text-align:left;">Truy vấn Kho Lưu Trữ Ảnh/Video, File, Link của nhóm và Cloud của tôi (Send2Me), cùng chuyển đổi Voice-to-Text AI.</td></tr><tr><td style="text-align:left;"><a href="./sticker.html"><strong>✨ Nhãn dán, GIF Giphy/Guggy &amp; Hiệu ứng (Sticker)</strong></a></td><td style="text-align:left;"><code>api.sticker</code></td><td style="text-align:center;"><strong>24</strong></td><td style="text-align:left;">Tìm kiếm nhãn dán, danh mục nhãn dán V2, nhãn dán gợi ý theo ngữ cảnh, kho ảnh động GIF (Giphy, Guggy, Tenor) và hiệu ứng tin nhắn nền (Message Effects).</td></tr><tr><td style="text-align:left;"><a href="./board.html"><strong>📌 Bảng tin, Bình chọn, Lịch hẹn &amp; Zalo To-Do (Board)</strong></a></td><td style="text-align:left;"><code>api.board</code></td><td style="text-align:center;"><strong>38</strong></td><td style="text-align:left;">Quản lý Tin ghim (Pin Topics), Ghi chú nhóm (Notes), Bình chọn (Polls), Lịch hẹn nhóm &amp; 1-1 (Reminders), Bảng tin bạn bè và Giao việc Zalo To-Do.</td></tr><tr><td style="text-align:left;"><a href="./business.html"><strong>💼 Zalo Business, OA, Nhãn CRM &amp; Danh mục (Business)</strong></a></td><td style="text-align:left;"><code>api.business</code></td><td style="text-align:center;"><strong>36</strong></td><td style="text-align:left;">Quản lý Zalo Official Account (getOAProfile, blockOA, unblockOA, convertOAIds), Nhãn phân loại hội thoại CRM (Labels), Tin nhắn nhanh (Quick Messages), Trả lời tự động (Auto Reply), Danh mục sản phẩm (Catalog) và Ngân hàng.</td></tr></tbody></table>',2))])}const f=o(s,[["render",h]]);export{y as __pageData,f as default};
